'use strict';
/* The experience layer only presents engine state. Scene acknowledgements never advance time. */
const exUI={all:localStorage.getItem('vestkyst-all-tools')==='on',sound:localStorage.getItem('vestkyst-sound')==='on',scene:null,audio:null,shown:0,section:'quests'};
const exText=v=>esc(v==null?'':v);
const exArr=v=>Array.isArray(v)?v:[];
const exDays=n=>exText(n)+' '+(Number(n)===1?'dag':'dager');
const exGet=(fn,...args)=>{try{return typeof G[fn]==='function'?G[fn](...args):null;}catch(_){return null;}};
const exGo=(target,label,cls='button ghost')=>`<button class="${cls}" data-view="${exText(target)}">${exText(label)}</button>`;
const exPortrait=(i=0)=>`<div class="ex-face ex-face-${i%4}">${portrait(i)}</div>`;
function exSound(){if(!exUI.sound)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;const ctx=exUI.audio||(exUI.audio=new AC());ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.setValueAtTime(330,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(490,ctx.currentTime+.12);g.gain.setValueAtTime(.025,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.2);o.connect(g).connect(ctx.destination);o.start();o.stop(ctx.currentTime+.21);}catch(_){}}
function exMoves(){return exArr(exGet('nextMoves',s)).slice(0,3);}
function exMoveCard(m,i){return `<article class="ex-move ${i===0?'ex-move-primary':''}"><span class="ex-step">0${i+1}</span><div><span class="section-kicker">${i===0?'DITT NESTE TREKK':'EN ANNEN VEI'}</span><h3>${exText(m.title)}</h3><p>${exText(m.text)}</p><button class="button ${i===0?'brass':'ghost'}" data-ex-move="${i}" ${m.disabled?'disabled':''}>${exText(m.label||'Gjør trekket')} <span aria-hidden="true">→</span></button>${m.reason?`<small>${exText(m.reason)}</small>`:''}</div></article>`;}
function exQuestCards(limit){const list=exArr(exGet('questList',s)).slice().sort((a,b)=>({active:0,locked:1,done:2}[a.status]??1)-({active:0,locked:1,done:2}[b.status]??1));return list.slice(0,limit||list.length).map((q,i)=>exQuest(q,i)).join('');}
function exContactName(id){return exArr(G.storyContacts).find(c=>c.id===id)?.name||id||'En kontakt';}
function exItemName(id){const items=G.QUEST_ITEMS||G.ITEMS||G.ITEM_DEFS||{};return (Array.isArray(items)?items.find(x=>x.id===id):items[id])?.name||id;}
function exQuest(q,i){const info=exGet('questInfo',s,q.id)||q,step=info.current||info;return `<article class="ex-quest"><div class="ex-quest-top"><span class="section-kicker">${exText(exContactName(info.contact))}</span><span class="ex-status">${exText(info.status==='done'?'Fullført':info.status==='locked'?'Et senere spor':info.ready?'Klar for ditt valg':'På sporet')}</span></div><h3>${exText(step.title||info.title||q.title)}</h3><p>${exText(step.text||info.intro)}</p>${step.objective?`<div class="ex-objective">↳ ${exText(step.objective)}</div>`:''}${exQuestDetails(info)}<button class="button ghost" data-ex-quest="${exText(q.id)}" ${info.status!=='done'&&!info.ready?'disabled':''}>${info.status==='done'?'Se saken':info.status==='locked'?'Åpner som '+(G.LEVELS[info.rank]?.name||'rang '+info.rank):!info.ready?'Bygg forutsetningene først':'Les og velg'} →</button></article>`;}
function exQuestDetails(q){const step=q.current||q,items=exArr(step.choices).map(c=>c.item).filter(Boolean);return `${q.total?`<p class="ex-progress-text">Spor ${Math.min(q.total,(q.step||0)+1)} av ${q.total}</p>${meter(Math.max(0,(q.step||0))/q.total*100)}`:''}${items.length?`<div class="ex-reward"><span>ET OBJEKT MED EN HISTORIE</span><b>${exText([...new Set(items)].map(exItemName).join(' / '))}</b></div>`:''}${q.reason&&!q.ready?`<p class="small">${exText(q.reason)}</p>`:''}`;}
function exContactLink(c){const quests=exArr(exGet('questList',s)),direct=quests.filter(q=>q.contact===c.id||q.current?.speaker===c.id),related=quests.filter(q=>exArr(G.QUEST_LINES).find(l=>l.id===q.id)?.steps.some(step=>step.speaker===c.id||step.choices.some(x=>x.contact===c.id))),list=direct.length?direct:related;return list.slice().sort((a,b)=>(a.status==='active'?0:a.status==='locked'?1:2)-(b.status==='active'?0:b.status==='locked'?1:2))[0]||null;}
function exContactGate(c,q){if((c.id==='bjornar'||c.id==='haugland')&&exGet('arcInfo',s)?.active)return null;if(!q)return 'Et nytt møte åpner senere i historien.';if(q.status==='locked')return 'Møtet åpner som '+(G.LEVELS[q.rank]?.name||'rang '+q.rank)+'.';if(q.status==='done')return null;if(!q.ready)return q.reason||q.current?.objective||'Følg sporet videre.';if(q.contact===c.id||q.current?.speaker===c.id)return null;return 'Neste møte etter «'+(q.current?.title||q.title)+'». '+(q.current?.objective||q.reason||'Følg oppdraget videre.');}
function exContacts(limit=4){const contacts=exArr(G.storyContacts);return contacts.slice(0,limit).map((c,i)=>{const q=exContactLink(c),gate=exContactGate(c,q);return `<button class="ex-contact" data-ex-contact="${exText(c.id||i)}" ${gate?'disabled':''}>${exPortrait(i)}<span><b>${exText(c.name)}</b><small>${exText(c.role||'Kontakt i Stavanger')}${s.story?.relationships?.[c.id]!=null?' · forhold '+(s.story.relationships[c.id]>0?'+':'')+exText(s.story.relationships[c.id]):''}</small><em>${exText(gate||c.voice)}</em>${q?`<span class="ex-contact-hook">${exText(q.status==='done'?'Se det dere gjorde sammen':q.current?.title||q.title)} ${gate?'':'→'}</span>`:''}</span><strong aria-hidden="true">${gate?'⌁':'↗'}</strong></button>`;}).join('');}
function exOpenContact(id){const c=exArr(G.storyContacts).find(c=>c.id===id);if(!c)return;const q=exContactLink(c),gate=exContactGate(c,q);if(gate)return;const arc=(c.id==='bjornar'||c.id==='haugland')&&exGet('arcInfo',s)?.active;modal(`<div class="ex-contact-dialog">${exPortrait(exArr(G.storyContacts).indexOf(c))}<span class="section-kicker">${exText(c.role)}</span><h2>${exText(c.name)}</h2><p>«${exText(c.voice)}»</p><p>${exText(c.bio)}</p>${q?`<div class="ex-contact-thread"><span class="section-kicker">${exText(q.title)}</span><h3>${exText(q.current?.title||'Historien dere deler')}</h3><p>${exText(q.current?.objective||q.intro)}</p>${q.reason&&q.status!=='done'?`<p>${exText(q.reason)}</p>`:''}<button class="button brass" data-ex-quest="${exText(q.id)}" ${q.status!=='done'&&!q.ready?'disabled':''}>${q.status==='done'?'Les det som skjedde':'Åpne samtalen'} →</button></div>`:''}${arc?'<button class="button ghost" data-ex-section="arc">Ta det siste oppgjøret →</button>':''}</div>`);}
const exPlaces=[
 {id:'vagen',name:'Vågen',district:'SENTRUM',symbol:'↔',text:'Lastelys i det svarte vannet. Et parti kan bli penger, men først må det faktisk komme hjem.',hooks:[{kind:'buy',label:'Møt en leverandør og planlegg reisen'},{kind:'sell',label:'Se dagens salg fra kofferten'},{kind:'crime',id:'rumor',label:'Lytt til ryktene rundt Vågen'}]},
 {id:'storhaug',name:'Verkstedet på Storhaug',district:'STORHAUG',symbol:'⚒',text:'Radioene står under en presenning. Raggen venter med lykta. Her bygger du et vennskap før du bygger et navn.',hooks:[{kind:'quest',id:'key',label:'Møt Raggen ved arbeidsbenken'}]},
 {id:'pedersgata',name:'Pedersgata',district:'ØST FOR SENTRUM',symbol:'▤',text:'Noras blå bok ligger åpen. Litt lenger nede i gata trenger en nabo hjelp med en vanskelig avtale.',hooks:[{kind:'quest',id:'book',label:'Sett deg ned med Nora'},{kind:'crime',id:'favor',label:'Hjelp naboen med avtalen'}]},
 {id:'fiskepiren',name:'Fiskepiren',district:'HAVNEKANTEN',symbol:'⇢',text:'Budene kommer før du rekker kaffen. Her finner du arbeid som krever at du faktisk stiller opp.',hooks:[{kind:'crime',id:'contact',label:'Still opp for kontakten din'},{kind:'buy',label:'Avtal et parti og en avgang'}]},
 {id:'taukaien',name:'Taukaien',district:'HAVNEKANTEN',symbol:'≈',text:'Tor ser på klokka, ikke på tittelen din. En avgang blir et løfte når andre er avhengige av den.',hooks:[{kind:'quest',id:'harbor',label:'Snakk med Tor om avgangen'},{kind:'crime',id:'night',label:'Les vilkårene for nattens oppdrag'}]},
 {id:'ostre',name:'Østre bydel',district:'STORHAUG',symbol:'✦',text:'Ada har funnet et tomt rom. Hvem som får plass her, sier mer om deg enn skiltet over døra.',hooks:[{kind:'quest',id:'table',label:'Hjelp Ada å fylle rommet'},{kind:'crime',id:'peace',label:'Prøv å megle før feiden vokser'}]},
 {id:'valand',name:'Kjøkkenbordet på Våland',district:'VÅLAND',symbol:'⌂',text:'Her kan telefonen ligge med skjermen ned. Tre dager til å samle krefter kan være et bedre trekk enn enda en avtale.',hooks:[{kind:'rest',label:'Ta tre dager til å hente deg inn'}]},
 {id:'lervig',name:'Lervig',district:'ØSTRE BYDEL',symbol:'⌁',text:'Laget venter mellom vaktene. Du kan hente nye folk, gi dem trening eller sørge for at de blir.',hooks:[{kind:'view',view:'crew',label:'Møt laget og velg neste steg'},{kind:'crime',id:'rescue',label:'Hjelp en gammel venn hjem'}]},
 {id:'breiavatnet',name:'Breiavatnet',district:'SENTRUM',symbol:'○',text:'En runde rundt vannet gir avstand til telefonene. Du velger selv om byen skal få tre dager uten deg.',hooks:[{kind:'rest',label:'Samle krefter og ro ned søkelyset'},{kind:'view',view:'legacy',label:'Velg hva du vil bli husket for'}]},
 {id:'valberg',name:'Valbergtårnet',district:'HOLMEN',symbol:'♜',text:'Herfra ser alle territoriene små ut. Rivalene ser på de samme gatene og planlegger sine egne trekk.',hooks:[{kind:'view',view:'rivals',label:'Undersøk rivalene før du svarer'},{kind:'crime',id:'rival',label:'Les rivalens neste trekk'}]},
 {id:'gamle',name:'Gamle Stavanger',district:'STRAEN',symbol:'◇',text:'Små gater har lange minner. Følg det som skjedde, eller bruk tid på en kontakt som trenger deg nå.',hooks:[{kind:'crime',id:'contact',label:'Stå ved kontakten din'},{kind:'view',view:'ledger',label:'Følg sporene i dine faktiske oppgjør'}]},
 {id:'stasjonen',name:'Stavanger stasjon',district:'KANNIK',symbol:'⇄',text:'Kartet slutter ikke ved kommunegrensa. En ny by krever mer enn en billett: kapital, ledelse og et navn som holder.',hooks:[{kind:'view',view:'cities',label:'Se byene og velg en etablering'},{kind:'buy',label:'Planlegg en innkjøpsreise'}]},
 {id:'holmen',name:'Bordet på Holmen',district:'HOLMEN',symbol:'♟',text:'Bjørnar bestiller alltid før du kommer. Et sete ved dette bordet kan koste mer enn regninga.',hooks:[{kind:'crime',id:'summit',label:'Les invitasjonen til det lukkede bordet'},{kind:'arc',label:'Svar Bjørnar i siste akt'}]},
 {id:'lagard',name:'Lagårdsveien',district:'LAGÅRD',symbol:'§',text:'I historien venter Haugland med spørsmål om avtalene dine. Du kan forberede et svar og velge hvem som skal bære ansvaret.',hooks:[{kind:'arc',label:'Vurder saken og velg en respons'},{kind:'quest',id:'book',label:'Gå gjennom dokumentasjonen med Nora'}]}
];
function exPlaceQuote(h){let reason=null,detail='';if(h.kind==='quest'){const q=exGet('questInfo',s,h.id);reason=!q?'Oppdraget er ikke tilgjengelig.':q.status==='locked'?q.reason:q.status!=='done'&&!q.ready?q.reason:null;detail=q?.current?.objective||q?.intro||'';}else if(h.kind==='crime'){const q=exGet('crimeQuote',s,h.id);reason=q?.reason||(!q?'Jobben er ikke tilgjengelig.':null);detail=q?Math.round(q.success*100)+' % suksess · '+exDays(q.days)+' · '+kr(q.reward)+' ved suksess':'';}else if(h.kind==='arc'){const a=exGet('arcInfo',s);reason=!a?.active?'Åpner som Gudfar eller i siste del av tiåret.':null;detail=a?.active?'Bjørnar: '+Math.round(a.rival.pressure)+'/100 press · saken: '+Math.round(a.case.evidence)+'/100 bevis':'';}else if(h.kind==='sell'){reason=!exArr(s.stock).some(n=>n>0)?'Kofferten er tom. Fullfør en innkjøpsreise først.':null;detail='Se dagens etterspørsel og oppgjøret før du selger.';}else if(h.kind==='buy'){detail='Velg land, varer, pris og faktisk reisetid.';}else if(h.kind==='rest'){detail='3 dager · +35 utholdenhet · +25 nerver · −6 søkelys · ukedrift løper.';}else if(h.view==='cities'){detail='Les kravene for hver by før du etablerer deg.';}if(s.ended&&!['view','quest','arc'].includes(h.kind))reason='Runden er avsluttet.';else if(s.trip&&!['view','quest','arc'].includes(h.kind))reason='Fullfør reisen først.';else if(s.event&&!['view','quest','arc'].includes(h.kind))reason='Ta den viktige avgjørelsen først.';return {reason,detail};}
function exPlaceCard(p,i){const options=p.hooks.map(exPlaceQuote),open=options.some(o=>!o.reason);return `<article class="ex-place ${open?'':'ex-place-locked'}"><span class="ex-place-sign" aria-hidden="true">${exText(p.symbol)}</span><div><span class="section-kicker">${String(i+1).padStart(2,'0')} / ${exText(p.district)}</span><h3>${exText(p.name)}</h3><p>${exText(p.text)}</p><span class="ex-place-now">${exText(open?p.hooks[options.findIndex(o=>!o.reason)].label:options[0]?.reason)}</span><button class="button ${open?'ghost':'locked'}" data-ex-place="${exText(p.id)}" ${open?'':'disabled'}>${open?'Gå dit og velg':'Ikke tilgjengelig ennå'} ${open?'→':''}</button></div></article>`;}
function exPlacePanel(){return `<section class="ex-places"><div class="ex-section-title"><div><span class="section-kicker">14 STEDER / ETT VALG OM GANGEN</span><h2>Hvor går du?</h2></div></div><p class="ex-place-intro">Et besøk åpner konkrete valg. Å se seg rundt bruker ingen spilltid; pris og dager står ved handlingen du velger. Personene og møtestedene i fortellingen er oppdiktet.</p><div class="ex-place-grid">${exPlaces.map(exPlaceCard).join('')}</div></section>`;}
function exVisit(id){const p=exPlaces.find(p=>p.id===id);if(!p)return;modal(`<div class="ex-visit"><span class="section-kicker">${exText(p.district)} / DU ER HER</span><h2>${exText(p.name)}</h2><p>${exText(p.text)}</p><div class="ex-visit-choices">${p.hooks.map((h,i)=>{const q=exPlaceQuote(h);return `<article><h3>${exText(h.label)}</h3><p>${exText(q.detail)}</p>${q.reason?`<p class="ex-gate">${exText(q.reason)}</p>`:''}<button class="button ${q.reason?'ghost':'brass'}" data-ex-place-action="${exText(p.id)}" data-ex-place-option="${i}" ${q.reason?'disabled':''}>${q.reason?'Forutsetning mangler':h.kind==='rest'?'Hent deg inn · 3 dager':'Se og velg'} →</button></article>`;}).join('')}</div><small>Du har ikke brukt tid ved å åpne dette stedet.</small></div>`);}
function exDoPlace(id,index){const p=exPlaces.find(p=>p.id===id),h=p?.hooks[index];if(!h||exPlaceQuote(h).reason)return;$('#dialog').close();if(h.kind==='quest')exOpenQuest(h.id);else if(h.kind==='crime')exOpenCrime(h.id);else if(h.kind==='buy')countries();else if(h.kind==='sell')sellMarket();else if(h.kind==='rest')act('crimeRest');else if(h.kind==='arc')exSection('arc');else if(h.kind==='view'){view=h.view;render();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}}
function exSection(section){if(!['quests','places','crime','arc'].includes(section))section='quests';exUI.section=section;view='experience';if($('#dialog').open)$('#dialog').close();render();window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function exArc(){const a=exGet('arcInfo',s);if(!a||!a.active)return '';return `<section class="ex-threat"><div class="ex-threat-symbol" aria-hidden="true">!</div><div><span class="section-kicker">BYEN SVARER / ${exDays(a.daysLeft).toUpperCase()} IGJEN</span><h2>${exText(a.title)}</h2><p>${exText(a.ending?.text||`${a.rival.name} presser nettverket ditt. ${a.case.name} følger sporene.`)}</p><div class="ex-arc-counts"><span>Rivalpress ${Math.round(a.rival.pressure)}/100</span><span>Bevis ${Math.round(a.case.evidence)}/100</span><span>Frist ${exText(a.closingDate)}</span><span>Akt ${exText(a.act||1)} av ${exText(a.maxActs||3)}</span>${a.control!=null?`<span>Kontroll ${Math.round(a.control)}/100</span>`:''}${a.nextActIn!=null?`<span>Neste akt om ${exDays(a.nextActIn)}</span>`:''}</div></div>${view==='experience'?'':'<button class="button ghost" data-ex-section="arc">Åpne siste akt →</button>'}</section>${view==='experience'?`${exArr(a.obligations).length?`<div class="ex-arc-obligations"><h3>Det avtalene koster videre.</h3>${exArr(a.obligations).map(o=>`<p><b>${exText(o.label)}</b> ${exText(o.text)}</p>`).join('')}<p>Betalt hittil: ${kr(a.obligationPaid||0)}</p></div>`:''}<div class="ex-arc-options">${[...exArr(a.preparations),...exArr(a.options)].map((o,i)=>`<article class="ex-arc-option"><h3>${exText(o.label)}</h3><p>${exText(o.text)}</p>${o.crewLossSuccess!=null?`<p>Medlemmer som forlater laget: ${exText(o.crewLossSuccess)} ved suksess, inntil ${exText(o.crewLossFailure)} ved nederlag.</p>`:''}${o.choice==='challenge'?'<p>Et tapt oppgjør kan koste ytterligere 8 % av kassa.</p>':''}<p>${kr(o.cost||0)} · ${exDays(o.days)}${o.success!=null?' · '+Math.round(o.success*100)+' % sjanse':''}</p>${o.reason?`<p>${exText(o.reason)}</p>`:''}<button class="button ghost" data-ex-arc="${i}" ${o.valid===false?'disabled':''}>${exText(o.label)} →</button></article>`).join('')}</div>`:''}`;}
const exPriorHome=home;
home=function(){const moves=exMoves();return `<div class="ex-home"><section class="ex-hero"><div class="harbor-image"></div><div class="ex-rain" aria-hidden="true"></div><div class="ex-hero-content"><span class="section-kicker">VÅGEN / ${exText(G.rank(s))} / KAPITTEL ${Math.min(7,(s.chapters||[]).length+1)}</span><h1>${s.ended?'BYEN HUSKER<br>VALGENE DINE.':'ET NAVN.<br>NOE Å MISTE.'}</h1><p>${s.ended?'Historien din ligger igjen i gatene. Se hva du bygde, og hvem som ble med deg.':'Regnet gir seg ikkje. Det gjør ikkje byen heller. Hvem ringer du, og hva setter du på spill?'}</p><div class="scene-buttons">${exGo('experience',s.ended?'Se historien din':'Finn et oppdrag','button brass')}${exGo('routes','Til kaien','button glass')}</div></div><div class="ex-live"><i></i> STAVANGER LEVER VIDERE</div></section><section class="ex-next"><div class="ex-section-title"><div><span class="section-kicker">DU BESTEMMER TEMPOET</span><h2>Ka gjør du nå?</h2></div><span>Tre veier videre. Ett valg om gangen.</span></div><div class="ex-moves">${moves.length?moves.map(exMoveCard).join(''):`<article class="ex-move"><div><h3>Byen venter på deg.</h3><p>Ta en prat på gata, eller gå til kaien og planlegg første handel.</p>${exGo('experience','Møt kontaktene','button brass')}</div></article>`}</div></section><section class="ex-city-invite"><div><span class="section-kicker">STAVANGER / 14 STEDER Å GÅ</span><h2>Du kjenner kaien. Ka med resten?</h2><p>Verkstedet, kjøkkenbordet, tårnet. Folk og muligheter har en adresse.</p></div><button class="button ghost" data-ex-section="places">Ut i byen →</button></section><div class="ex-story-grid"><section><div class="ex-section-title"><div><span class="section-kicker">FOLK HAR LANGE MINNER</span><h2>På linja.</h2></div>${exGo('experience','Alle spor ↗','text-button')}</div><div class="ex-contacts">${exContacts()||`<div class="ex-contact">${exPortrait(0)}<span><b>Raggen</b><small>Din kontakt på kaien</small><em>«Du kan ikkje stå her resten av livet.»</em></span></div>`}</div></section><section><div class="ex-section-title"><div><span class="section-kicker">HISTORIEN DIN</span><h2>Uferdige saker.</h2></div></div><div class="ex-quests">${exQuestCards(2)||mission()}</div></section></div>${exArc()}${exObjects()}<section class="ex-recent"><span class="section-kicker">DET BYEN HUSKER</span>${exArr(s.log).slice(0,2).map(t=>`<p>↳ ${exText(t)}</p>`).join('')||'<p>Det første trekket er ditt.</p>'}</section></div>`;};
function exObjects(){const owned=exArr(s.items?.owned);return owned.length?`<section class="ex-objects"><div class="ex-section-title"><div><span class="section-kicker">TING DU HAR FORTJENT</span><h2>Det du tar med deg.</h2></div></div><div class="ex-object-grid">${owned.map(id=>{const item=G.QUEST_ITEMS?.[id];return `<article><span aria-hidden="true">◇</span><h3>${exText(item?.name||id)}</h3><p>${exText(item?.text)}</p>${Object.entries(item?.modifiers||{}).map(([k,v])=>`<small>${exText(({income:'Lokalinntekt',travelCost:'Reisekostnad',heatGain:'Søkelys',trainingCost:'Treningskostnad',salePrice:'Salgspris',routeReliability:'Rutepålitelighet'})[k]||k)} ${v>1?'+':''}${Math.round((v-1)*100)} %</small>`).join('')}</article>`;}).join('')}</div></section>`:'';}
function exStory(){const section=exUI.section,arc=exGet('arcInfo',s);return `<div class="ex-story"><div class="page-title"><div><span class="section-kicker">KONTAKTER / 14 STEDER / DINE VALG</span><h1>GATA HAR<br>ALLTID ET SVAR.</h1><p>Velg hvem du stoler på, hvor du går og hva du setter på spill.</p></div>${exGo('home','← Tilbake til Vågen')}</div><div class="ex-section-tabs" role="group" aria-label="Velg hva du vil gjøre">${[['quests','Oppdrag'],['places','Byen · 14 steder'],['crime','Jobber på gata'],['arc','Siste akt']].map(([id,label])=>`<button data-ex-section="${id}" class="${section===id?'selected':''}" aria-pressed="${section===id}" ${id==='arc'&&!arc?.active?'disabled':''}>${label}</button>`).join('')}</div>${section==='places'?exPlacePanel():section==='crime'?`<section><h2 class="section-heading">En sjanse på gata.</h2><div class="ex-crime-grid">${exCrimes()}</div></section>`:section==='arc'?exArc():`<div class="ex-story-grid"><section><h2 class="section-heading">Saker som venter.</h2><div class="ex-quests">${exQuestCards()||'<article class="ex-quest"><h3>Ingen uløste saker akkurat nå.</h3><p>Ta neste trekk fra Vågen.</p></article>'}</div></section><section><h2 class="section-heading">Folk på linja.</h2><div class="ex-contacts">${exContacts(99)}</div></section></div>${exObjects()}`}</div>`;}
function exCrimes(){const stats=s.crime;return `${stats?`<div class="ex-crime-terms"><span>Utholdenhet <b>${Math.round(stats.stamina)}/100</b></span><span>Nerver <b>${Math.round(stats.nerve)}/100</b></span></div><button class="button ghost" data-act="crimeRest">Hent deg inn · 3 dager →</button>`:''}${exArr(exGet('crimeList',s)).map(q=>`<article class="ex-crime"><span class="section-kicker">GATA / NIVÅ ${exText(q.level)}</span><h3>${exText(q.name)}</h3><p>${exText(q.text)}</p><div class="ex-crime-terms"><span>Suksess <b>${Math.round(q.success*100)} %</b></span><span>Tid <b>${exDays(q.days)}</b></span><span>Belønning <b>${kr(q.reward)}</b></span></div><p class="small">${exText(q.reason||`${q.stamina} utholdenhet · ${q.nerve} nerver · ${kr(q.cost)} innsats`)}</p><button class="button ghost" data-ex-crime="${exText(q.id)}" ${q.valid===false?'disabled':''}>Se risiko og belønning →</button></article>`).join('')}`;}
function exOpenQuest(id){const q=exGet('questInfo',s,id);if(!q)return;const step=q.current||q;modal(`<span class="section-kicker">${exText(exContactName(step.speaker||q.contact))} / ${exText(q.title)}</span><h2>${exText(step.title||q.title)}</h2><p>${exText(step.text||q.intro)}</p>${step.objective?`<div class="ex-objective">${exText(step.objective)}</div>`:''}${exQuestDetails(q)}${q.status==='done'?`<div class="ex-history">${exArr(q.history).map(h=>`<p>✓ ${exText(h.title)}<small>${exText(h.label)} · dag ${exText(h.day)}</small></p>`).join('')}</div>`:''}<div class="ex-dialog-choices">${exArr(step.choices).map((c,i)=>`<button class="choice" data-ex-quest-choice="${exText(id)}" data-ex-choice="${exText(c.id??i)}" ${!q.ready||c.allowed===false?'disabled':''}>${exText(c.label)}<small>${exDays(c.days||0)} · ${kr(c.cost||0)} innsats${c.relation?' · forhold '+(c.relation>0?'+':'')+exText(c.relation):''}${c.heat?' · søkelys '+(c.heat>0?'+':'')+exText(c.heat):''}${c.loyalty?' · lojalitet '+(c.loyalty>0?'+':'')+exText(c.loyalty):''}${c.influence?' · innflytelse '+(c.influence>0?'+':'')+exText(c.influence):''}${c.cash?' · '+kr(c.cash)+' i belønning':''}${c.item?' · '+exText(exItemName(c.item)):''}</small>${c.reason?`<small>${exText(c.reason)}</small>`:''}</button>`).join('')}</div>`);}
function exOpenCrime(id){const q=exGet('crimeQuote',s,id);if(!q)return;modal(`<span class="section-kicker">ET BEVISST VALG / STAVANGER</span><h2>${exText(q.name)}</h2><p>${exText(q.text)}</p><div class="ex-crime-terms"><span>Suksess <b>${Math.round(q.success*100)} %</b></span><span>Komplikasjon <b>${Math.round(q.complication*100)} %</b></span><span>Kritisk utfall <b>${Math.round(q.critical*100)} %</b></span></div><div class="ex-crime-terms"><span>Tid <b>${exDays(q.days)}</b></span><span>Innsats <b>${kr(q.cost)}</b></span><span>Ved suksess <b>${kr(q.reward)}</b></span></div><p>${exText(q.stamina)} utholdenhet og ${exText(q.nerve)} nerver. Komplikasjoner og kritiske utfall kan koste penger, søkelys og folk.${q.crewRisk?' Folk fra laget er utsatt.':''} Ved komplikasjon: ${kr(q.complicationReward||0)} i utbetaling. Et kritisk utfall koster totalt ${kr(q.criticalLoss||0)} inkludert innsats.</p>${q.reason?`<p>${exText(q.reason)}</p>`:''}<div class="ex-dialog-choices"><button class="button brass" data-ex-crime-start="${exText(id)}" ${q.valid===false?'disabled':''}>Ta sjansen →</button><button class="button ghost" data-ex-close>La det ligge</button></div>`);}
if(!nav.some(n=>n[0]==='experience'))nav.splice(1,0,['experience','02','Gata']);
nav.forEach((n,i)=>n[1]=String(i+1).padStart(2,'0'));
const exPriorRender=render;
render=function(){const current=view;if(current==='experience')view='home';exPriorRender();view=current;if(current==='experience')$('#screen').innerHTML=exStory();const navEl=$('#nav');navEl.querySelectorAll('[data-view]').forEach(n=>{const active=n.dataset.view===current;n.classList.toggle('active',active);if(active)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');const basic=['home','experience','routes','crew','rivals'].includes(n.dataset.view);n.hidden=!exUI.all&&!basic&&!active;});navEl.insertAdjacentHTML('beforeend',`${exGet('pendingScene',s)?'<button data-ex-inbox>Meldinger ● '+exArr(s.experience?.scenes).length+'</button>':''}<button class="ex-all-tools" data-ex-all aria-expanded="${exUI.all}">${exUI.all?'Færre valg −':'Vis alle +'}<span>${nav.length} visninger</span></button>`);const version=document.querySelector('footer>span');if(version)version.textContent='VESTKYST / SPILLBAR ALFA 0.7';document.body.classList.add('experience-on');document.body.classList.toggle('ex-all-visible',exUI.all);exQueueScene();};
const exSceneDialog=document.createElement('dialog');exSceneDialog.id='experienceScene';exSceneDialog.setAttribute('aria-label','En melding fra byen');document.body.append(exSceneDialog);
const exPriorAct=act;act=function(type,arg){exUI.shown=0;return exPriorAct(type,arg);};
const exIsOutcome=x=>/result|outcome|ending|crime|warning/i.test(x.kind)||/result/i.test(x.id);
let exSceneTimer;
function exQueueScene(){clearTimeout(exSceneTimer);exSceneTimer=setTimeout(exShowScene,180);}
function exShowScene(){const scene=exArr(s.experience?.scenes).slice().reverse().find(exIsOutcome)||exGet('pendingScene',s);if(!scene||exSceneDialog.open||exUI.shown)return;if(document.querySelector('dialog[open]')){exSceneTimer=setTimeout(exShowScene,400);return;}exUI.scene=scene.id;exSceneDialog.innerHTML=`<div class="ex-scene ${['level','rank','levelup'].includes(scene.kind)?'ex-scene-level':''}"><div class="ex-scene-portrait">${exPortrait(Math.max(0,exArr(G.storyContacts).findIndex(c=>c.id===scene.speaker||c.name===scene.speaker)))}<span class="section-kicker">${exText(exContactName(scene.speaker||'BYEN'))}</span></div><div class="ex-scene-content"><span class="section-kicker">${exText(['level','rank','levelup'].includes(scene.kind)?'ET NYTT NAVN PÅ GATA':exIsOutcome(scene)?'DETTE BLE FØLGENE':'EN MELDING TIL DEG')}</span><h2>${exText(scene.title)}</h2><p>${exText(scene.text)}</p>${exIsOutcome(scene)&&scene.day===s.day&&s.summary?`<div class="ex-outcome-receipt"><span>${exDays(s.summary.days||0)} senere</span><b>${s.summary.net>=0?'+':''}${kr(s.summary.net||0)} i kassa</b><small>Inkluderer driften mens tiden gikk.</small></div>`:''}${scene.item?`<div class="ex-scene-object"><span class="section-kicker">ET SPOR DU TAR MED DEG</span><h3>◇ ${exText(exItemName(scene.item))}</h3><p>${exText(G.QUEST_ITEMS?.[scene.item]?.text||'')}</p></div>`:''}${exArr(scene.lines).map(l=>`<p class="ex-scene-line">${exText(typeof l==='object'?l.text:l)}</p>`).join('')}${scene.kind==='quest'&&scene.quest?`<button class="button brass" data-ex-scene-quest="${exText(scene.quest)}">Les og svar →</button>`:'<button class="button brass" data-ex-scene-close>Tilbake til byen →</button>'}</div><button class="ex-scene-skip" data-ex-scene-close aria-label="Lukk melding">×</button></div>`;exSceneDialog.showModal();exUI.shown=1;exSound();}
function exDismiss(){if(exUI.scene!=null&&typeof G.dismissScene==='function'){G.dismissScene(s,exUI.scene);save();}exUI.scene=null;exSceneDialog.close();render();}
exSceneDialog.addEventListener('cancel',e=>{e.preventDefault();exDismiss();});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-ex-section'))exSection(b.dataset.exSection);if(b.hasAttribute('data-ex-place'))exVisit(b.dataset.exPlace);if(b.hasAttribute('data-ex-place-action'))exDoPlace(b.dataset.exPlaceAction,+b.dataset.exPlaceOption);if(b.hasAttribute('data-ex-all')){exUI.all=!exUI.all;localStorage.setItem('vestkyst-all-tools',exUI.all?'on':'off');render();}if(b.hasAttribute('data-ex-move')){const m=exMoves()[Number(b.dataset.exMove)];if(!m||m.disabled)return;exSound();if(m.ui==='buy'){countries();return;}if(m.ui==='sell'){sellMarket();return;}if(m.action)act(m.action,m.arg);if(m.view){if(m.view==='experience'){exUI.section=m.arg?.section==='crime'?'crime':m.arg?.section==='arc'?'arc':'quests';}view=m.view;render();if(m.arg?.quest){exOpenQuest(m.arg.quest);} window.scrollTo({top:0,behavior:'smooth'});}}if(b.hasAttribute('data-ex-contact'))exOpenContact(b.dataset.exContact);if(b.hasAttribute('data-ex-quest'))exOpenQuest(b.dataset.exQuest);if(b.hasAttribute('data-ex-quest-choice')){act('questChoice',{quest:b.dataset.exQuestChoice,choice:b.dataset.exChoice});$('#dialog').close();exQueueScene();}if(b.hasAttribute('data-ex-crime'))exOpenCrime(b.dataset.exCrime);if(b.hasAttribute('data-ex-crime-start')){$('#dialog').close();exSound();act('crimeAttempt',b.dataset.exCrimeStart);}if(b.hasAttribute('data-ex-arc')){const a=exGet('arcInfo',s),o=[...exArr(a?.preparations),...exArr(a?.options)][+b.dataset.exArc];if(o&&o.valid!==false)act(o.action,o.arg);}if(b.hasAttribute('data-ex-inbox')){exUI.shown=0;exShowScene();}if(b.hasAttribute('data-ex-close'))$('#dialog').close();if(b.hasAttribute('data-ex-scene-quest')){const id=b.dataset.exSceneQuest;exDismiss();exOpenQuest(id);}if(b.hasAttribute('data-ex-scene-close'))exDismiss();});
const exPriorSettings=$('#settings').onclick;
$('#settings').onclick=()=>{exPriorSettings();$('#dialogBody').insertAdjacentHTML('beforeend',`<hr><label class="check-label"><input id="exSoundToggle" type="checkbox" ${exUI.sound?'checked':''}> Diskrete lyder ved egne valg</label><p class="small">Valgfritt. Ingen musikk. Du kan slå av når som helst.</p>`);$('#exSoundToggle').onchange=e=>{exUI.sound=e.target.checked;localStorage.setItem('vestkyst-sound',exUI.sound?'on':'off');exSound();};};
render();
